CustomField.formula:
IF(Audi_Digital_Program__c, "Audi",
	IF(BMW_Website_Program__c, "BMW",
		IF(Honda_Website_Digital_Program__c, "Honda",
			IF(Kia_Website_Program__c , "Kia", 
				IF(Maserati_OEM_Digital_Program__c , "Maserati", 
					IF(Mazda_Digital_Certified_Program__c ,"Mazda", 
						IF(Mitsubishi_Website_Program__c ,"Mitsubishi",
							IF(Porsche_Website_Program__c , "Porsche",
								IF(Subaru_OEM_Program__c , "Subaru",
									IF(Acura_Digital_Certified_Program__c , "Acura",
										IF( VW_Website_Program__c , "VW", "Standard")
									)
								)
							)
						)
					)
				)
			)
		)
	)
)
